import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {View} from 'react-native';
import TextCM from '../../../../components/Text';
import {IconRoundDocument, IconRoundUser} from '../../../../../assets/images';
import {INumberReceipt} from '../..';

type DataType = {
  title: string;
  value: number;
  icon: React.ReactNode;
};

type Props = {
  numberReceipt: INumberReceipt;
};

const Statistical = ({numberReceipt}: Props) => {
  const {t} = useTranslation();

  const data: DataType[] = [
    {
      title: 'BLDT.receipt_overview',
      value: numberReceipt.numberReceipt,
      icon: <IconRoundDocument width={48} height={48} />,
    },
    {
      title: 'BLDT.number_fund_receipt',
      value: numberReceipt.numberReceiptFundSubmited,
      icon: <IconRoundUser width={48} height={48} />,
    },
    {
      title: 'BLDT.number_pending_fund_receipt',
      value: numberReceipt.numberReceiptPendingFundSubmited,
      icon: <IconRoundUser width={48} height={48} />,
    },
  ];

  const renderItem = (item: DataType) => {
    return (
      <View style={styles.viewItem} key={item.title}>
        {item.icon}
        <View>
          <TextCM style={styles.txtValue}>{formatNumber(item.value)}</TextCM>
          <TextCM style={styles.txtName}>{t(item.title)}</TextCM>
        </View>
      </View>
    );
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('BLDT.txt_statistical')}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default Statistical;
