import {createBottomTabNavigator} from '@react-navigation/bottom-tabs';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import {
  Pressable,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import {} from '../../constants/Size';
import {
  IconDashboard,
  IconDashboardSelect,
  IconMyReceipt,
  IconMyReceiptSelect,
  IconNotification,
  IconNotificationSelect,
  IconPlus,
  IconReceiptProcess,
  IconReceiptProcessSelect,
} from '../../assets/images';
import TextCM from '../../app/components/Text';
import {useTranslation} from 'react-i18next';
import {useEffect, useState} from 'react';
import {useAppDispatch} from '../../hooks/useRedux';
import {BottomTabitem, listBottomTab, TabName} from './helper';
import BottomSheetCM from '../../app/components/BottomSheet';
import CreateNewScreen from '../../app/screen/create-new';
import {useZutandStore} from '../../zutand/store';
import {PermissionUtils} from '../../utils';

const Tabs = createBottomTabNavigator();

const MyTabBar = ({
  state,
  navigation,
  t,
  totalRecoders,
  width,
  setIsShowCreate,
  listMenuViewBLDT,
  isShowCreate,
}: any) => {
  return (
    <SafeAreaView
      edges={['bottom', 'left', 'right']}
      style={styles.ctnSafeTabBottom}>
      <View style={[styles.ctnTabBottom]}>
        {state.routes.map((route: any, index: number) => {
          let label = '';
          const isFocused = state.index === index;
          function getIcon() {
            switch (route.name) {
              case TabName.DashboardScreen:
                label = t('BLDT.txt_statistical');
                return (
                  <>
                    {isFocused ? (
                      <IconDashboardSelect width={23} height={20} />
                    ) : (
                      <IconDashboard width={23} height={20} />
                    )}
                  </>
                );
              case TabName.MyReceiptScreen:
                label = t('BLDT.my_receipt');
                return (
                  <>
                    {isFocused ? (
                      <IconMyReceiptSelect width={23} height={20} />
                    ) : (
                      <IconMyReceipt width={23} height={20} />
                    )}
                  </>
                );
              case TabName.ReceiptProcessScreen:
                label = t('BLDT.receipt_need_approval');
                return (
                  <>
                    {isFocused ? (
                      <IconReceiptProcessSelect width={23} height={20} />
                    ) : (
                      <IconReceiptProcess width={23} height={20} />
                    )}
                  </>
                );
              case TabName.NotificationScreen:
                label = t('CM.noti');
                return (
                  <View style={{position: 'relative'}}>
                    {totalRecoders > 0 && (
                      <View
                        style={{
                          position: 'absolute',
                          backgroundColor: '#e14337',
                          borderRadius: 100,
                          paddingHorizontal: 4,
                          paddingVertical: 2,
                          top: -5,
                          right: totalRecoders > 100 ? -20 : -12,
                        }}>
                        <TextCM
                          style={{
                            fontSize: 10,
                            color: '#fff',
                          }}>
                          {totalRecoders < 100 ? totalRecoders : '99+'}
                        </TextCM>
                      </View>
                    )}
                    {isFocused ? (
                      <IconNotificationSelect width={23} height={20} />
                    ) : (
                      <IconNotification width={23} height={20} />
                    )}
                  </View>
                );

              default:
                break;
            }
          }

          const onPress = () => {
            const event = navigation.emit({
              type: 'tabPress',
              target: route.key,
              canPreventDefault: true,
            });

            if (!isFocused && !event.defaultPrevented) {
              navigation.navigate(route.name, route.params);
            }
          };

          return (
            <TouchableOpacity
              accessibilityRole="button"
              style={[styles.ctnItemTabBottom]}
              accessibilityState={isFocused ? {selected: true} : {}}
              key={index}
              onPress={onPress}>
              {getIcon()}
              <TextCM
                style={isFocused ? styles.txtLabelSelect : styles.txtLabel}>
                {label}
              </TextCM>
            </TouchableOpacity>
          );
        })}
      </View>
      {listMenuViewBLDT?.find(
        (item: any) => item.nameId === 'bldt.create-receipt',
      ) && (
        <Pressable
          onPress={() => setIsShowCreate(true)}
          style={{
            ...styles.icon,
            left: (width - 38) / 2,
          }}>
          <IconPlus width={23} height={20} />
        </Pressable>
      )}

      <BottomSheetCM
        onClose={() => setIsShowCreate(false)}
        isVisible={isShowCreate}
        renderContent={
          <CreateNewScreen onClose={() => setIsShowCreate(false)} />
        }
        title={t('GS.history.createNew')}
      />
    </SafeAreaView>
  );
};

const BottomTabNavigationEBLDT = () => {
  const {t} = useTranslation();
  const dispatch = useAppDispatch();
  const [totalRecoders, setTotalRecoders] = useState(0);
  const {width} = useWindowDimensions();
  const [isShowCreate, setIsShowCreate] = useState(false);
  const [listBottomTabPermission, setListBottomTabPermission] = useState<
    BottomTabitem[]
  >([]);
  const {listMenuViewBLDT} = useZutandStore();

  useEffect(() => {
    if (listMenuViewBLDT?.length > 0) {
      setListBottomTabPermission(
        listBottomTab.filter((itemBottomTab: any) => {
          return PermissionUtils.hasPermission(
            listMenuViewBLDT,
            itemBottomTab.permission,
          );
        }),
      );
    }
  }, [listMenuViewBLDT]);

  return (
    <>
      {listBottomTabPermission?.length ? (
        <Tabs.Navigator
          tabBar={props => (
            <MyTabBar
              {...props}
              t={t}
              totalRecoders={totalRecoders}
              width={width}
              setIsShowCreate={setIsShowCreate}
              listMenuViewBLDT={listMenuViewBLDT}
              isShowCreate={isShowCreate}
            />
          )}
          screenOptions={{headerShown: false}}>
          {listBottomTabPermission?.map(item => {
            return (
              <Tabs.Screen
                key={item.name}
                name={item.name}
                component={item.component}
              />
            );
          })}
        </Tabs.Navigator>
      ) : (
        <View />
      )}
    </>
  );
};

export default BottomTabNavigationEBLDT;
